/** @type {import('tailwindcss').Config} */

// Every color below resolves to a CSS variable defined in src/app/theme.css
// (generated by scripts/generate-theme.mjs), so the whole UI switches between
// light and dark mode by toggling the `dark` class on <html>.
const HUES = [
  "blue", "green", "red", "purple", "amber", "emerald", "yellow", "orange",
  "pink", "indigo", "cyan", "teal", "rose", "sky", "violet", "lime", "fuchsia",
];
const SHADES = ["50", "100", "200", "300", "400", "500", "600", "700", "800", "900", "950"];

const scale = (prefix) =>
  Object.fromEntries(SHADES.map((s) => [s, `rgb(var(--${prefix}-${s}) / <alpha-value>)`]));

const themed = Object.fromEntries(HUES.map((h) => [h, scale(h)]));
const themedText = Object.fromEntries(HUES.map((h) => [h, scale(`tx-${h}`)]));
const neutral = scale("slate");

// Fixed (non-switching) dark navy for elements that are dark in both themes.
const ink = { 700: "#334155", 800: "#1e293b", 900: "#0f172a", 950: "#020617" };

module.exports = {
  darkMode: "class",
  content: ["./src/**/*.{js,jsx,ts,tsx}"],
  theme: {
    extend: {
      colors: {
        ...themed,
        slate: neutral,
        gray: neutral,
        ink,
        canvas: "rgb(var(--canvas) / <alpha-value>)",
        surface: "rgb(var(--surface) / <alpha-value>)",
        brand: { DEFAULT: "#1e65f3", dark: "#0a2342" },
      },
      // bg-white / from-white / to-white follow the theme; text-white & border-white stay white.
      // Use bg-glass/10 for translucent white overlays that must stay white in dark mode.
      backgroundColor: {
        white: "rgb(var(--white-surface) / <alpha-value>)",
        glass: "#ffffff",
      },
      gradientColorStops: {
        white: "rgb(var(--white-surface) / <alpha-value>)",
      },
      textColor: () => ({
        ...themedText,
        slate: neutral,
        gray: neutral,
      }),
      fontFamily: {
        sans: ["var(--font-inter)", "ui-sans-serif", "system-ui", "sans-serif"],
      },
    },
  },
  plugins: [],
};
